package net.civeira.phylax.feature.observe.observedissuealias.application.usecase.create;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueReference;
import net.civeira.phylax.feature.observe.observedissuealias.domain.ObservedIssueAliasChangeSet;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

class ObservedIssueAliasCreateInputUnitTest {

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the observed issue alias input values are kept when converted to a change set and back")
  void test_observed_issue_alias_create_input_change_set_round_trip() {
    ObservedIssueAliasCreateInput input =
        ObservedIssueAliasCreateInput.builder().uid("one").origin(ObservedSourceReference.of("one"))
            .fingerprint("one").issue(ObservedIssueReference.of("one")).version(1).build();
    ObservedIssueAliasChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    ObservedIssueAliasCreateInput copy = ObservedIssueAliasCreateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getOrigin().isPresent(), "origin must be assigned by the builder");
    Assertions.assertEquals(input.getOrigin(), copy.getOrigin(),
        "origin must survive the change set round trip");
    Assertions.assertTrue(input.getFingerprint().isPresent(),
        "fingerprint must be assigned by the builder");
    Assertions.assertEquals(input.getFingerprint(), copy.getFingerprint(),
        "fingerprint must survive the change set round trip");
    Assertions.assertTrue(input.getIssue().isPresent(), "issue must be assigned by the builder");
    Assertions.assertEquals(input.getIssue(), copy.getIssue(),
        "issue must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the observed issue alias input builder can generate a new identifier")
  void test_observed_issue_alias_create_input_new_uid() {
    ObservedIssueAliasCreateInput input = ObservedIssueAliasCreateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        ObservedIssueAliasCreateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the observed issue alias input starts empty and the setters assign values")
  void test_observed_issue_alias_create_input_setters() {
    ObservedIssueAliasCreateInput empty = ObservedIssueAliasCreateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getOrigin().isEmpty(), "origin must be empty by default");
    Assertions.assertSame(empty, empty.setOrigin(ObservedSourceReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getOrigin().isPresent(), "origin must be assigned by the setter");
    Assertions.assertTrue(empty.getFingerprint().isEmpty(), "fingerprint must be empty by default");
    Assertions.assertSame(empty, empty.setFingerprint("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getFingerprint().isPresent(),
        "fingerprint must be assigned by the setter");
    Assertions.assertTrue(empty.getIssue().isEmpty(), "issue must be empty by default");
    Assertions.assertSame(empty, empty.setIssue(ObservedIssueReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getIssue().isPresent(), "issue must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
